\label{def:QR}
Let $\mathscr H$ be a real Hilbert space. Given
$\mathbf F=(f_1,\dots,f_q)^\top\in\mathscr H^q$ and
$\mathbf G=(g_1,\dots,g_m)^\top\in\mathscr H^m$, set
$V\coloneqq\operatorname{span}\{f_1,\dots,f_q\}\subset\mathscr H$.
Define the Gram matrix and cross-Gram matrix by
\begin{equation}
\begin{aligned}
R(\mathbf F)
\coloneqq
\bigl(\langle f_i,f_j\rangle_{\mathscr H}\bigr)_{i,j=1}^q
\in\mathbb{R}^{q\times q},
\label{eq:R-general}
\end{aligned}
\end{equation}
and
\begin{equation}
\begin{aligned}
Q(\mathbf G,\mathbf F)
\coloneqq
\bigl(\langle g_i,f_j\rangle_{\mathscr H}\bigr)_{\substack{i=1,\dots,m\\ j=1,\dots,q}}
\in\mathbb{R}^{m\times q}.
\label{eq:Q-general}
\end{aligned}
\end{equation}

\label{lem:gram-invertible}
\label{thm:general-proj}
Let $\mathscr H$ be a real Hilbert space and
$\mathbf F=(f_1,\dots,f_q)^\top\in\mathscr H^q$.
Then $R(\mathbf F)\succ0$ if and only if $f_1,\dots,f_q$ are linearly
independent in $\mathscr H$. In this case, $V=\operatorname{span}\{f_1,\dots,f_q\}$
is closed and, for every $\mathbf G\in\mathscr H^m$,
\begin{equation}
\Pi_{V^m}\mathbf G
=
Q(\mathbf G,\mathbf F)R(\mathbf F)^{-1}\mathbf F.
\label{eq:general-proj}
\end{equation}

\label{ass:CCK-membership}
The functions $\pi_1,\dots,\pi_\ell$ are linearly independent in
$\mathcal H$.

\label{thm:reduced-family}
Under Assumption~\ref{ass:CCK-membership}, the raw lift family can be
reduced to a nested family that is linearly independent of the
actuator-coordinate subspace. More precisely, there exist
$M\in\mathbb{N}\cup\{0,\infty\}$, a strictly increasing sequence of indices
$\{j_k\}_{k=1}^{M}\subset\mathbb{N}$ (empty if $M=0$), and an
$\mathcal H$-orthonormal family
$\{\widehat\phi_k\}_{k=1}^{M}\subset C(\Omega,\mathbb{R})$ such that, for every
$N$ with $1\le N\le M$,
\begin{equation}
\begin{aligned}
V_N
\coloneqq
\operatorname{span}\{\widehat\phi_1,\dots,\widehat\phi_N\}
=
\operatorname{span}\{\phi_{j_1}^{\mathrm{raw}},\dots,\phi_{j_N}^{\mathrm{raw}}\}
\subset\mathcal H,
\label{eq:VCCK-WN}
\end{aligned}
\end{equation}
and $U_p\cap V_N=\{0\}$.
Consequently,
\begin{equation}
\begin{aligned}
W_N
\coloneqq
U_p\oplus V_N
=
U_p+\operatorname{span}\{\phi_{j_1}^{\mathrm{raw}},\dots,\phi_{j_N}^{\mathrm{raw}}\},
\label{eq:WN-characterization}
\end{aligned}
\end{equation}
and $W_N\subset W_{N+1}$ whenever $1\le N<M$. In particular, each
$\widehat\phi_k$ is a finite real linear combination of raw lifts.

If $M=0$, then all raw lifts belong to $U_p$. If
$1\le M<\infty$, then
\begin{equation}
\begin{aligned}
U_p+\operatorname{span}\{\phi_k^{\mathrm{raw}}:k\ge1\}
=
U_p\oplus V_M.
\label{eq:finite-M}
\end{aligned}
\end{equation}
Hence, if $\bigl(U_p+\operatorname{span}\{\phi_k^{\mathrm{raw}}:k\ge1\}\bigr)/U_p$
is infinite-dimensional, then $M=\infty$.

\label{def:CCK-reduced}
Let $M\in\mathbb{N}\cup\{0,\infty\}$ and
$\{\widehat\phi_k\}_{k=1}^{M}$ be as in
Theorem~\ref{thm:reduced-family}. For $1\le N\le M$, define
\begin{equation}
\begin{aligned}
\mathbf\Phi_N
\coloneqq
\operatorname{col}(\widehat\phi_1,\dots,\widehat\phi_N)
\in C(\Omega,\mathbb{R}^N),
\label{eq:PhiN}
\end{aligned}
\end{equation}
\begin{equation}
\begin{aligned}
\bm\pi
\coloneqq
\operatorname{col}(\pi_1,\dots,\pi_\ell)
\in C(\Omega,\mathbb{R}^\ell),
\quad
\bm\pi(p,x)=p,
\label{eq:pi-vector}
\end{aligned}
\end{equation}
and
\begin{equation}
\begin{aligned}
\mathbf Z_N
\coloneqq
\operatorname{col}(\bm\pi,\mathbf\Phi_N)
\in C(\Omega,\mathbb{R}^{\ell+N}).
\label{eq:ZN}
\end{aligned}
\end{equation}

For $1\le k\le M$, define the nominal Lie derivative
\begin{equation}
\begin{aligned}
\widehat\gamma_k(p,x)
\coloneqq
D_p\widehat\phi_k(p,x)A_pp
+
D_x\widehat\phi_k(p,x)f(x,C_pp).
\label{eq:gammahat}
\end{aligned}
\end{equation}
For $1\le N\le M$, set
\begin{equation}
\begin{aligned}
\boldsymbol\gamma_N(p,x)
&\coloneqq
\operatorname{col}\bigl(
\widehat\gamma_1(p,x),\dots,\widehat\gamma_N(p,x)
\bigr)\\
&=
D_p\mathbf\Phi_N(p,x)A_pp
+D_x\mathbf\Phi_N(p,x)f(x,C_pp).
\end{aligned}
\label{eq:GammaCCK}
\end{equation}
Define also
\begin{equation}
\begin{aligned}
\widehat J_N(p,x)
\coloneqq
D_p\mathbf\Phi_N(p,x)
\in\mathbb{R}^{N\times\ell},
\label{eq:Jhat}
\end{aligned}
\end{equation}
and the augmented nominal derivative field
\begin{equation}
\begin{aligned}
\mathbf\Gamma_N(p,x)
\coloneqq
\operatorname{col}\bigl(
A_p\bm\pi(p,x),
\boldsymbol\gamma_N(p,x)
\bigr)
\in\mathbb{R}^{\ell+N}.
\label{eq:Upsilon}
\end{aligned}
\end{equation}

\label{lem:lower-block-exactB}
For each $k$ with $1\le k\le M$,
$\widehat\gamma_k\in C(\Omega,\mathbb{R})$ and
\begin{equation}
\begin{aligned}
D_p\widehat\phi_k(p,x)B_p=0
\ \text{for all }(p,x)\in\Omega.
\label{eq:exactB-scalar}
\end{aligned}
\end{equation}
Consequently, for every $1\le N\le M$, $D_p\mathbf\Phi_N(p,x)B_p=0$
on $\Omega$, and $\boldsymbol\gamma_N$ and $\mathbf\Gamma_N$ are continuous.

\label{thm:main-CCK}
Fix a reduced order $N$ with $1\le N\le M$. Define the closure
residual field by
\begin{equation}
\begin{aligned}
\mathbf r_N
\coloneqq
\mathcal R_{W_N^N}\boldsymbol\gamma_N
\in C(\Omega,\mathbb{R}^N).
\label{eq:rCCK}
\end{aligned}
\end{equation}
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item
The following field identity holds pointwise on $\Omega$:
\begin{equation}
\mathbf\Gamma_N
=
A_N\mathbf Z_N
+
\operatorname{col}\bigl(0_\ell,\mathbf r_N\bigr).
\label{eq:Upsilon-split}
\end{equation}
    \item if $I\subset\mathbb{R}$ is an interval and
    $(p(\cdot),x(\cdot),u_a(\cdot))
    \in C^1(I;P\times X\times\mathbb{R}^m)$ satisfies
\begin{equation}
\begin{aligned}
\dot p(t)
&= A_pp(t)+B_pu_a(t)+\delta_p(t),\\
\dot x(t)
&= f\bigl(x(t),C_pp(t)\bigr), \ (p(t),x(t))
\in\Omega
\end{aligned}
\label{eq:trajectory-CCK}
\end{equation}
    for all $t\in I$, then the evaluated lifted state
\begin{equation}
\begin{aligned}
    \zeta_N(t)
    \coloneqq
    \mathbf Z_N(p(t),x(t))
    \in\mathbb{R}^{\ell+N}
    \label{eq:zeta}
\end{aligned}
\end{equation}
   satisfies
\begin{equation}
\dot\zeta_N(t)
=
A_N\zeta_N(t)
+
B_Nu_a(t)
+
\Delta_N(t)
\label{eq:main-CCK-ODE}
\end{equation}
for all $t\in I$, where
\begin{equation}
\begin{aligned}
    \Delta_N(t)
    \coloneqq
    \begin{bmatrix}
    \delta_p(t)\\
    \mathbf r_N(p(t),x(t))
    +
    \widehat J_N(p(t),x(t))\delta_p(t)
    \end{bmatrix}.
    \label{eq:Delta}
\end{aligned}
\end{equation}
\end{enumerate}

\label{cor:uniform-uncertainty}
Fix $1\le N\le M$. By continuity and compactness, the maxima
below are finite and attained. These are the smallest scalar bounds for the fixed dictionary,
coordinates, region, and measure. Define
\begin{equation}
\begin{aligned}
\rho_N^{\star}
&\coloneqq\max_{\vartheta\in\Omega}\|\mathbf r_N(\vartheta)\|_2,\\
L_N^{\star}
&\coloneqq\max_{\vartheta\in\Omega}\|\widehat J_N(\vartheta)\|_{2\to2},
\label{eq:rho-L}
\end{aligned}
\end{equation}
and, for $\delta\ge0$,
\begin{equation}
\sigma_{c,N}^{\star}(\delta)
\coloneqq
\max_{\substack{\vartheta\in\Omega\\d\in\mathbb{R}^\ell,\ \|d\|_2\le\delta}}
\|\mathbf r_N(\vartheta)+\widehat J_N(\vartheta)d\|_2.
\label{eq:sigma-c-s6}
\end{equation}
The triangle inequality gives the following bound:
\begin{equation}
\sigma_{c,N}^{\star}(0)=\rho_N^\star,
\qquad
\sigma_{c,N}^{\star}(\delta)\le\rho_N^\star+L_N^\star\delta.
\label{eq:sigma-c-properties}
\end{equation}

\label{cor:cck-readouts}
Fix $N$ with $1\le N\le M$.
\begin{enumerate}[label=\textnormal{(\roman*)}]

\item
Using the standing embedding convention, define
\begin{equation}
\begin{aligned}
C_{y,N}
\coloneqq
\left(
\int_\Omega h Z_N^\top\,d\mu
\right)R_N^{-1}
\mathrel{\in}\mathbb{R}^{n_y\times(\ell+N)}.
\label{eq:cck-output-readout}
\end{aligned}
\end{equation}
Set $v_{y,N}
\coloneqq
h-C_{y,N}\mathbf Z_N
\in C(\Omega,\mathbb{R}^{n_y})$.
Then
\begin{equation}
\begin{aligned}
h
=
C_{y,N}\mathbf Z_N+v_{y,N}
\label{eq:cck-output-readout-residual}
\end{aligned}
\end{equation}
pointwise on $\Omega$, and
\begin{equation}
\begin{aligned}
\nu_N^{\star}
\coloneqq
\max_{\vartheta\in\Omega}
\|v_{y,N}(\vartheta)\|_2
<\infty.
\label{eq:nu-star}
\end{aligned}
\end{equation}

\item
Suppose that, for every $i\in\{1,\dots,n\}$, there exist
$k_i\le j_N$ and $a_i\ne0$ such that
\begin{equation}
\begin{aligned}
\psi_{k_i}(x,u)=a_i x_i.
\label{eq:state-coordinate-retention}
\end{aligned}
\end{equation}
Then $x\in W_N^n$, and
\begin{equation}
\begin{aligned}
H_{x,N}
\coloneqq
Q(x,\mathbf Z_N)R_N^{-1}
\in\mathbb{R}^{n\times(\ell+N)}
\label{eq:HxN}
\end{aligned}
\end{equation}
satisfies
\begin{equation}
x = H_{x,N}\mathbf Z_N(p,x),
\quad \forall (p,x)\in\Omega.
\label{eq:exact-state-readout}
\end{equation}
Consequently, defining $\xi\coloneqq\operatorname{col}(p,x)$ and
\begin{equation}
\begin{aligned}
H_{\xi,N}
\coloneqq
\begin{bmatrix}
\begin{array}{cc}
I_\ell & 0_{\ell\times N}
\end{array}\\[1mm]
H_{x,N}
\end{bmatrix}
\in\mathbb{R}^{(\ell+n)\times(\ell+N)},
\label{eq:HxiN}
\end{aligned}
\end{equation}
one has
\begin{equation}
\begin{aligned}
\xi
=
H_{\xi,N}\mathbf Z_N(p,x),\ \forall(p,x)\in\Omega.
\label{eq:exact-augmented-state-readout}
\end{aligned}
\end{equation}
\end{enumerate}

\label{thm:closure-criterion}
For every $1\le N\le M$,
\begin{equation}
\begin{aligned}
\|\mathbf r_N\|_{\mathcal H^N}^2
=
\sum_{k=1}^N
\operatorname{dist}_{\mathcal H}^2(\widehat\gamma_k,W_N).
\label{eq:best-approx}
\end{aligned}
\end{equation}

\label{cor:uniform-closure}
Fix $N$ with $1\le N\le M$. For $g\in C(\Omega,\mathbb{R})$, define
\begin{equation}
\widetilde\Pi_{W_N}g
\coloneqq
\left(
\int_\Omega g Z_N^\top\,d\mu
\right)R_N^{-1}Z_N.
\label{eq:Pi-tilde}
\end{equation}
Then $\widetilde\Pi_{W_N}:C(\Omega,\mathbb{R})\to C(\Omega,\mathbb{R})$ is a bounded linear projection with range $W_N$. Moreover, for every
$g\in C(\Omega,\mathbb{R})$,
\begin{equation}
\widetilde\Pi_{W_N}g
=
\Pi_{W_N}g
\quad\text{in }\mathcal H.
\label{eq:Pi-coincides}
\end{equation}
Define
\begin{equation}
\Lambda_N
\coloneqq
\|\widetilde\Pi_{W_N}\|_{C(\Omega)\to C(\Omega)}.
\label{eq:LambdaN}
\end{equation}
Then
\begin{equation}
\rho_N^\star
\le
(1+\Lambda_N)
\left(
\sum_{k=1}^{N}
\inf_{w\in W_N}
\|\widehat\gamma_k-w\|_{L^\infty(\Omega)}^2
\right)^{1/2}.
\label{eq:uniform-closure-bound}
\end{equation}

\label{prop:outer-realization}
Under Assumption~\ref{ass:feedback-setting}, let
$(p,x,u_a)$ be a maximal trajectory of
\eqref{eq:actuator} and \eqref{eq:plant-augmented}, with
$\tau_{\Omega,N}$ defined by \eqref{eq:first-exit-s6}. Then, on
$[0,\tau_{\Omega,N})$, the lifted trajectory
\[
\zeta_N(t)
\coloneqq
\mathbf Z_N\bigl(p(t),x(t)\bigr)
\]
satisfies the LTI dynamics
\begin{align}
\dot\zeta_N
&=
A_N\zeta_N+B_Nu_a
+\delta E_{p,N}w_{p,N}
+\sigma_{c,N}^{\star}E_{c,N}w_{c,N}
\quad\text{a.e.},
\notag\\
y
&=
C_{y,N}\zeta_N+\nu_N^{\star}w_{v,N},
\label{eq:outer-realization}
\end{align}
for measurable channels $w_{p,N}$, $w_{c,N}$, and $w_{v,N}$,
representing the normalized actuator defect, lower-block uncertainty,
and output-readout residual, respectively, and taking values in
$\mathbb{R}^\ell$, $\mathbb{R}^N$, and $\mathbb{R}^{n_y}$,
\begin{equation}
\begin{aligned}
\|w_{p,N}(t)\|_2\le1,\
\|w_{c,N}(t)\|_2\le1,\
\|w_{v,N}(t)\|_2\le1
\label{eq:normalized-bounds-s6}
\end{aligned}
\end{equation}
a.e. on $[0,\tau_{\Omega,N})$.

\label{ass:hinf-feasibility}

For the selected order $N$, $(A_{G,N},B_{2,N})$ is stabilizable and
$(A_{G,N},C_{2,N})$ is detectable. The feedthrough and frequency-domain rank conditions
for continuous-time $\mathcal{H}_\infty$ synthesis hold, and the normalization and, where needed,
loop-shifting transformations are well defined at
each tested performance level.

\label{thm:lyapunov-are}
For any $\gamma_{N,\mathrm a}
>
\|T_{zw,N}\|_\infty$, there exist
$P_N=P_N^\top\succ0$ and $\varepsilon_N>0$ such that
\begin{equation}
\begin{aligned}
V_{\mathrm{cl},N}(\chi_N)
\coloneqq
\chi_N^\top P_N\chi_N
\label{eq:lyapunov-function-s6}
\end{aligned}
\end{equation}
satisfies
\begin{equation}
\begin{aligned}
\dot V_{\mathrm{cl},N}
+
\|z_N\|_2^2
+
\varepsilon_N\|\chi_N\|_2^2
-
\gamma_{N,\mathrm a}^2\|w_N\|_2^2
\le0 \quad
\text{a.e.}
\label{eq:dissipation-s6}
\end{aligned}
\end{equation}
along \eqref{eq:closed-loop-realization-s6}.

\label{cor:lyapunov-estimates}
Under the hypotheses of Theorem~\ref{thm:lyapunov-are}, define
\begin{equation}
\begin{aligned}
a_N
\coloneqq
\frac{\varepsilon_N}{\lambda_{\max}(P_N)}
>0.
\label{eq:aN-s6}
\end{aligned}
\end{equation}
Then
\begin{equation}
\begin{aligned}
V_{\mathrm{cl},N}(t)
\le
e^{-a_Nt}V_{\mathrm{cl},N}(0)
+
\frac{\gamma_{N,\mathrm a}^2}{a_N}
\bigl(1-e^{-a_Nt}\bigr)m_{w,N}^2
\label{eq:V-bound-s6}
\end{aligned}
\end{equation}
for every $0\le t<\tau_{\Omega,N}$.

\label{thm:preexit-uub}
Under the hypotheses of Theorem~\ref{thm:lyapunov-are}, at any order
$N$ satisfying \eqref{eq:state-coordinate-retention}, every nonlinear
closed-loop trajectory covered by Proposition~\ref{prop:outer-realization}
satisfies
\begin{equation}
\begin{aligned}
\|\xi(t)\|_2
\le
\kappa_{\xi,N}
\left[\begin{gathered}
e^{-a_Nt}V_{\mathrm{cl},N}(0)\\
+
\frac{\gamma_{N,\mathrm a}^2}{a_N}
\bigl(1-e^{-a_Nt}\bigr)m_{w,N}^2
\end{gathered}\right]^{1/2}
\label{eq:preexit-state-s6}
\end{aligned}
\end{equation}
for every $0\le t<\tau_{\Omega,N}$. Moreover,
\begin{equation}
\begin{aligned}
&\|r(t)-h(x(t))\|_2\\
&\quad\le
\kappa_{e,N}
\left[
e^{-a_Nt}V_{\mathrm{cl},N}(0)
+
\frac{\gamma_{N,\mathrm a}^2}{a_N}
\bigl(1-e^{-a_Nt}\bigr)m_{w,N}^2
\right]^{1/2}
\\
&\quad +
\|D_{e,N}\|_{2\to2}m_{w,N}
\label{eq:preexit-error-s6}
\end{aligned}
\end{equation}
for almost every $0\le t<\tau_{\Omega,N}$.

\label{thm:regional-completion}

Under the hypotheses of Theorem~\ref{thm:preexit-uub}, let
$\xi(0)\in\operatorname{int}\Omega$ and
$\zeta_N(0)=\mathbf Z_N(\xi(0))$. Suppose that
\begin{equation}
\begin{aligned}
\mathfrak E_{\xi,N}(c_N)\subset\operatorname{int}\Omega,
\label{eq:containment-s6}
\end{aligned}
\end{equation}
or that alternative \textnormal{(ii)} above satisfies
$H_{f,N}\mathfrak E_{f,N}(c_{\mathrm{loc},N})\subset\operatorname{int}\Omega$,
or that alternative \textnormal{(iii)} has $r\in\mathscr R$ and
$d_i<b_i$ for every physical coordinate.
Then the nonlinear closed-loop trajectory is forward complete and
\begin{equation}
\begin{aligned}
\xi(t)\in\mathfrak E_{\xi,N}(c_N)\cap\operatorname{int}\Omega
,\quad t\ge0.
\label{eq:regional-invariance-s6}
\end{aligned}
\end{equation}
The estimates of Theorem~\ref{thm:preexit-uub} hold for all time, with
\begin{align}
&\limsup_{t\to\infty}\|\xi(t)\|_2
\le\kappa_{\xi,N}\frac{\gamma_{N,\mathrm a}}{\sqrt{a_N}}
\bar m_{w,N},
\label{eq:state-UUB-s6}\\
&\operatorname*{ess\,limsup}_{t\to\infty}\|r(t)-h(x(t))\|_2
\notag\\*[-2pt]
&\quad\le\left(\kappa_{e,N}\frac{\gamma_{N,\mathrm a}}{\sqrt{a_N}}
+\|D_{e,N}\|_{2\to2}\right)\bar m_{w,N}.
\label{eq:error-UUB-s6}
\end{align}
